"""The analyst of the dual agent: what one supplier thread tells us, kept current in the background.

On every supplier e-mail `Analyst.observe` updates a thread-safe `Intel` snapshot in two layers:

  structured  from the API, no model: standing term sheet and its move since the last round, status,
              signals, claim results, missing fields, who wrote (`from`) - plus code reading of the
              body: offers stated only in prose, cost drivers ("LCI-C rose 2.7 % ... 30 % of our
              cost"), questions, a rough tone. Ready at once.
  model       one extraction call per e-mail (JSON) in a worker thread: the same items read better,
              plus constraints, lever hints, tone, relationship style, withdraw language. Every
              figure it returns must appear in the e-mail, or it is dropped - the model reads, it
              never chooses a number.

Code then does the arithmetic: the C of every prose offer, the weighted cost impact of the stated
drivers against the requested increase, data claims for newly named indices, and `walk_risk` over
the whole thread. Between e-mails a worker mines the dossier for clues about the open gap.
"""

import copy
import json
import logging
import re
import threading
import time
from dataclasses import asdict, dataclass, field

from . import claims as cl
from . import runlog, writing
from .cost import complete_offer, must_haves_ok, total_cost
from .docs import standard_terms

log = logging.getLogger("arena")

BOSS_ROLES = {"boss", "owner", "md", "ceo", "management", "director", "head", "gf", "board", "managing"}
# walk_risk: points per signal, summed and clipped to 1
WALK_WEIGHTS = {
    "final_offer": 0.45,
    "price_unchanged_2_rounds": 0.25,
    "price_unchanged_1_round": 0.10,
    "reply_delay_rising": 0.10,
    "validity_shrinking": 0.10,
    "escalated_to_boss": 0.15,
    "tone_drop": 0.20,
    "withdraw_language": 0.30,
}
STALE_TOL = 0.001  # a move under 0.1 % of C is no move
WITHDRAW = re.compile(
    r"\b(withdraw\w*|end (?:our|the|these) (?:talks|negotiation|discussion)s?|no further (?:concession|movement|room)s?|"
    r"cannot go (?:any )?(?:lower|further)|our last word|last offer|look elsewhere|terminate|break off|"
    r"not continue|step back from)\b",
    re.I,
)
POSITIVE = re.compile(r"\b(happy|pleased|glad|appreciate\w*|fair point|thank\w*|value|welcome|good cooperation)\b", re.I)
NEGATIVE = re.compile(
    r"\b(disappoint\w*|unacceptable|cannot accept|regret\w*|insult\w*|surpris\w*|frustrat\w*|"
    r"not acceptable|no reciprocal|final)\b",
    re.I,
)
RELATIONSHIP = re.compile(
    r"\b(generations?|family|long-standing|partnership|our foundry|regional partners|loyal\w*|years of)\b", re.I
)
MONTHS = {
    m: i + 1
    for i, ms in enumerate(
        [
            ("january", "januar", "jan"), ("february", "februar", "feb"), ("march", "märz", "mar"),
            ("april", "apr"), ("may", "mai"), ("june", "juni", "jun"), ("july", "juli", "jul"),
            ("august", "aug"), ("september", "sep", "sept"), ("october", "oktober", "oct", "okt"),
            ("november", "nov"), ("december", "dezember", "dec", "dez"),
        ]  # fmt: skip
    )
    for m in ms
}
PRICE = re.compile(r"(?:€|EUR)\s?(\d{1,6}(?:[.,]\d{1,2})?)|(\d{1,6}(?:[.,]\d{1,2})?)\s?(?:€|EUR\b|euros?\b)", re.I)
PAYMENT = re.compile(
    r"(?:zahlungsziel|payment(?: terms?)?(?: at| of| in)?)\s+(\d{1,3})\s+(?:days|tage)|(\d{1,3})\s+(?:days|tage)\s+net",
    re.I,
)
ISO = re.compile(r"\b(20\d\d-\d\d-\d\d)\b")
LONG_DATE = re.compile(r"\b(\d{1,2})\.?\s+([A-Za-zä]+)\s+(20\d\d)\b")
LEAD = re.compile(r"lead time (?:of )?(\d{1,3}) days", re.I)
MONTHS_TERM = re.compile(r"\b(\d{1,2})[- ]month", re.I)
VOLUME = re.compile(r"\b(\d{1,3}(?:[.,]\d{3})+|\d{3,6})\s+(?:pcs|pieces|units)\s+(?:per|a)\s+year", re.I)
NOT_THEIRS = re.compile(r"\byou (?:offered|proposed|suggest\w*)\b|\byour (?:offer|price|proposal) of\b", re.I)
OFFER_WORDS = re.compile(
    r"\b(alternatively|we (?:can|could|would|propose|offer)|our (?:price|offer|angebot)|beside this|in return|"
    r"price of|lower our price)\b",
    re.I,
)
DRIVER_VERB = re.compile(
    r"(?P<name>[\w-]+(?: [\w-]+){0,3}?)\s+(?:has |have )?(?P<verb>rose|risen|increased|went up|climbed|grew|"
    r"fell|dropped|decreased|went down|declined)\s+(?:by\s+)?(?P<chg>[+-]?\d+(?:[.,]\d+)?)\s?%",
    re.I,
)
SHARE = re.compile(
    r"(?P<share>\d+(?:[.,]\d+)?)\s?%\s+of\s+(?:our|the|its)\s+(?:total\s+|production\s+|unit\s+)?(?:cost|costs|price)",
    re.I,
)
CLUE_WORDS = (
    "cash", "liquidity", "payment", "skonto", "discount", "capacity", "volume", "contract", "index", "energy",
    "electricity", "gas", "wage", "labour", "steel", "scrap", "approval", "effective", "hold", "price",
    "short-time", "bank", "order book", "utilisation", "utilization", "lead time", "invest",
)  # fmt: skip

ANALYST_SYSTEM = """You are a procurement analyst reading one e-mail from an industrial supplier to our
purchasing team. Extract what it says - do not judge or advise. Copy every figure exactly as written.

Return ONE JSON object and nothing else:
{"prose_offers": [{"unit_price": 0.0, "payment_days": null, "effective_date": null, "other_terms": {},
                   "quote": "the sentence"}],
 "cost_drivers": [{"name": "LCI-C or 'energy'", "change_pct": 0.0, "cost_share_pct": null, "quote": "..."}],
 "named_indices": ["index series codes named, e.g. PPI-D351"],
 "constraints": ["limits they state, e.g. 'earliest effective date is 2027-01-01'"],
 "lever_hints": [{"field": "a negotiable field", "hint": "what they want or offer on it"}],
 "tone": 0,
 "relationship_style": "relationship | formal | transactional",
 "withdraw_language": false,
 "questions_to_us": ["questions they asked us"],
 "missing_info": ["what we still do not know that would help us, e.g. 'cost breakdown'"]}

- prose_offers: every price the supplier offers in the text with the terms it is tied to, including
  alternatives ("Alternatively, with 30 days net: EUR 137.00"). Not prices we offered, not old prices.
  effective_date as YYYY-MM-DD.
- tone: -2 (hostile) .. +2 (warm). withdraw_language: true only if they threaten to end the talks or
  withdraw the offer."""


@dataclass
class Mail:
    """One supplier e-mail, as walk_risk reads it."""

    status: str | None = None
    c: float | None = None  # C of its standing sheet
    price: float | None = None
    delay: float | None = None
    validity: float | None = None
    role: str | None = None
    tone: float | None = None
    withdraw: bool = False


@dataclass
class Intel:
    supplier_id: str
    mails: int = 0
    status: str | None = None
    sender: str | None = None
    standing: dict = field(default_factory=dict)  # {id, terms, c}
    delta: dict = field(default_factory=dict)  # vs the previous supplier mail: {price, c}
    offers: list = field(default_factory=list)  # every sheet of its latest mail: {id, terms, c}
    signals: dict = field(default_factory=dict)
    claim_results: list = field(default_factory=list)
    missing_fields: list = field(default_factory=list)
    unchanged_rounds: int = 0
    prose_offers: list = field(default_factory=list)  # {terms, c, beats_standing, in_sheet, quote, source}
    cost_drivers: list = field(default_factory=list)  # {name, series, change_pct, share_pct, data_change_pct}
    cost_impact_pct: float | None = None
    asked_pct: float | None = None
    cost_gap_pct: float | None = None
    new_claims: list = field(default_factory=list)  # claims.Claim for indices they named
    constraints: list = field(default_factory=list)
    lever_hints: list = field(default_factory=list)
    tone: float | None = None
    relationship_style: str | None = None
    withdraw_language: bool = False
    questions: list = field(default_factory=list)
    missing_info: list = field(default_factory=list)
    clues: list = field(default_factory=list)  # {source, text}
    walk_risk: float = 0.0
    walk_signals: dict = field(default_factory=dict)
    llm: str = "off"  # the model layer for the latest mail: off | pending | done | failed
    updated_at: float = 0.0

    def to_log(self):
        d = asdict(self)
        d["new_claims"] = [{"key": c.key, "sentence": c.sentence, "favourable": c.favourable} for c in self.new_claims]
        return d


# --- the arithmetic -------------------------------------------------------------------------------
def weighted_impact(drivers):
    """The price effect of cost drivers, in %: Σ change × cost share (drivers without a share skip)."""
    parts = [d["change_pct"] * d["share_pct"] / 100 for d in drivers if d.get("share_pct") is not None]
    return round(sum(parts), 2) if parts else None


def walk_risk(mails):
    """(0..1, {signal: points}) over the whole thread, oldest mail first."""
    if not mails:
        return 0.0, {}
    last, prev = mails[-1], mails[:-1]
    if last.status == "walked_away":
        return 1.0, {"walked_away": 1.0}
    sig = {}
    if last.status == "final_offer":
        sig["final_offer"] = WALK_WEIGHTS["final_offer"]
    if (n := unchanged(mails)) >= 2:
        sig["price_unchanged_2_rounds"] = WALK_WEIGHTS["price_unchanged_2_rounds"]
    elif n == 1:
        sig["price_unchanged_1_round"] = WALK_WEIGHTS["price_unchanged_1_round"]
    delays = [m.delay for m in prev if m.delay is not None]
    if last.delay is not None and delays and last.delay > min(delays):
        sig["reply_delay_rising"] = WALK_WEIGHTS["reply_delay_rising"]
    valid = [m.validity for m in prev if m.validity is not None]
    if last.validity is not None and valid and last.validity < max(valid):
        sig["validity_shrinking"] = WALK_WEIGHTS["validity_shrinking"]
    if _boss(last.role) and any(m.role and not _boss(m.role) for m in prev):
        sig["escalated_to_boss"] = WALK_WEIGHTS["escalated_to_boss"]
    tones = [m.tone for m in prev if m.tone is not None]
    if last.tone is not None and tones and tones[-1] - last.tone >= 2:
        sig["tone_drop"] = WALK_WEIGHTS["tone_drop"]
    if last.withdraw:
        sig["withdraw_language"] = WALK_WEIGHTS["withdraw_language"]
    return round(min(1.0, sum(sig.values())), 2), sig


def unchanged(mails):
    """How many replies in a row left the standing offer where it was (in C, else price)."""
    n = 0
    for a, b in zip(reversed(mails[:-1]), reversed(mails[1:]), strict=True):
        x, y = (a.c, b.c) if a.c and b.c else (a.price, b.price)
        if x is None or y is None or abs(x - y) > STALE_TOL * x:
            break
        n += 1
    return n


def _boss(role):
    return bool(role) and any(w in role.lower() for w in BOSS_ROLES)


# --- reading the text by code ----------------------------------------------------------------------
def _num(text):
    text = text.replace(" ", "")
    if re.fullmatch(r"\d{1,3}(?:[.,]\d{3})+", text):
        return float(re.sub(r"[.,]", "", text))
    return float(text.replace(",", "."))


def _date(sentence):
    if m := ISO.search(sentence):
        return m.group(1)
    for d, mon, y in LONG_DATE.findall(sentence):
        if (k := MONTHS.get(mon.lower())) and 1 <= int(d) <= 31:
            return f"{y}-{k:02d}-{int(d):02d}"
    return None


def prose_terms(sentence, negotiable):
    """The terms one sentence states: {field: value} for the negotiable fields it names."""
    t = {}
    prices = [m.group(1) or m.group(2) for m in PRICE.finditer(sentence)]
    if prices:
        t["unit_price"] = _num(prices[-1])  # "from EUR 126.53 to EUR 138.55": the new one
    if "payment_days" in negotiable and (m := PAYMENT.search(sentence)):
        t["payment_days"] = int(m.group(1) or m.group(2))
    if "effective_date" in negotiable and re.search(r"\b(from|ab|effective|valid|start)", sentence, re.I):
        if d := _date(sentence):
            t["effective_date"] = d
    if "lead_time_days" in negotiable and (m := LEAD.search(sentence)):
        t["lead_time_days"] = int(m.group(1))
    if "contract_months" in negotiable and (m := MONTHS_TERM.search(sentence)):
        t["contract_months"] = int(m.group(1))
    if "volume_per_year" in negotiable and (m := VOLUME.search(sentence)):
        t["volume_per_year"] = int(_num(m.group(1)))
    return t


def prose_offers_by_code(body, negotiable):
    out = []
    for s in writing.sentences(re.sub(r"\s*\n\s*", " ", body or "")):
        if NOT_THEIRS.search(s) or not OFFER_WORDS.search(s):
            continue
        t = prose_terms(s, negotiable)
        if t.get("unit_price"):
            out.append({"terms": t, "quote": s.strip(), "source": "code"})
    return out


def drivers_by_code(body, series_ids=()):
    out = []
    for s in writing.sentences(re.sub(r"\s*\n\s*", " ", body or "")):
        verb, share = DRIVER_VERB.search(s), SHARE.search(s)
        if not verb:
            continue
        chg = _num(verb.group("chg").lstrip("+"))
        if verb.group("verb").lower() in ("fell", "dropped", "decreased", "went down", "declined"):
            chg = -abs(chg)
        name = verb.group("name").split()[-1]
        series = next((i for i in series_ids if i.lower() == name.lower()), None)
        out.append(
            {
                "name": name,
                "series": series,
                "change_pct": chg,
                "share_pct": _num(share.group("share")) if share else None,
                "quote": s.strip(),
                "source": "code",
            }
        )
    return out


def tone_by_code(body):
    pos, neg = len(POSITIVE.findall(body or "")), len(NEGATIVE.findall(body or ""))
    return max(-2.0, min(2.0, round((pos - 2 * neg) / 2)))


def _appears(value, text):
    """A figure the model returned is real only if the e-mail has it."""
    if value is None:
        return False
    v = float(value)
    forms = {f"{v:.2f}", f"{v:.1f}", f"{v:g}", f"{v:.2f}".replace(".", ","), f"{v:.1f}".replace(".", ",")}
    if v == int(v):
        forms.add(str(int(v)))
    return any(re.search(rf"(?<![\d.,]){re.escape(f)}(?![\d])", text) for f in forms)


# --- the analyst -----------------------------------------------------------------------------------
class Analyst:
    """One supplier thread. `observe` is called with every new state of the thread; `snapshot` is
    safe to call from any thread at any time."""

    def __init__(self, case, sid, package=None, dossier=None, complete=None, pool=None, rec=None):
        self.case, self.sid, self.package, self.dossier = case, sid, package, dossier or {}
        self.complete, self.pool, self.rec = complete, pool, rec
        self._lock = threading.Lock()
        self._intel = Intel(supplier_id=sid, llm="off" if complete is None else "pending")
        self._llm = {}  # mail index -> parsed model extraction
        self._pending = {}  # mail index -> Future
        self._events = []
        self.series_ids = self._series_ids()
        self.known_claims = set()

    def _series_ids(self):
        ids = set()
        if self.package is not None and getattr(self.package, "db", None):
            try:
                ids |= {r["id"] for r in self.package.query("SELECT id FROM index_series")}
            except Exception:
                pass
        ids |= {k[4:].split("@")[0] for k in (self.case.get("facts") or {}) if k.startswith("idx:")}
        return sorted(ids, key=len, reverse=True)

    # -- the interface ---------------------------------------------------------------------------
    def observe(self, events):
        """A new state of the thread: structured layer now, the model layer in the background."""
        with self._lock:
            self._events = list(events)
        self._rebuild()
        mails = [i for i, m in enumerate(events) if m.get("from") != "buyer"]
        if self.complete is not None and self.pool is not None and mails:
            i = mails[-1]
            with self._lock:
                start = i not in self._llm and i not in self._pending
                if start:
                    self._pending[i] = self.pool.submit(self._extract, i, events[i])
                    self._intel.llm = "pending"
        if self.pool is not None:
            self.pool.submit(self._mine)
        return self

    def wait(self, timeout):
        """Wait up to `timeout` seconds for the model layer of the latest mail; True if it is in."""
        with self._lock:
            futures = list(self._pending.values())
        deadline = time.monotonic() + max(0.0, timeout)
        for f in futures:
            try:
                f.result(timeout=max(0.0, deadline - time.monotonic()))
            except Exception:
                return False
        return True

    def snapshot(self):
        with self._lock:
            return copy.deepcopy(self._intel)

    # -- the structured layer --------------------------------------------------------------------
    def _rebuild(self):
        with self._lock:
            events, llm = list(self._events), dict(self._llm)
            clues = self._intel.clues
        case, negotiable = self.case, self.case["negotiable"]
        std = standard_terms(events)
        sup = [(i, m) for i, m in enumerate(events) if m.get("from") != "buyer"]
        if not sup:
            return
        intel = Intel(supplier_id=self.sid, mails=len(sup), clues=clues)

        def c(terms):
            try:
                return total_cost(case, terms, std) if terms.get("unit_price") else None
            except Exception:
                return None

        history = []
        for i, m in sup:
            sheets = m.get("term_sheets") or []
            terms = sheets[0]["terms"] if sheets else {}
            x = llm.get(i) or {}
            sig = m.get("signals") or {}
            history.append(
                Mail(
                    status=m.get("status"),
                    c=c(terms),
                    price=terms.get("unit_price"),
                    delay=sig.get("reply_delay_days"),
                    validity=sig.get("validity_days"),
                    role=(m.get("from") or "").split("@")[0] or None,
                    tone=x.get("tone") if isinstance(x.get("tone"), int | float) else tone_by_code(m.get("body")),
                    withdraw=bool(x.get("withdraw_language")) or bool(WITHDRAW.search(m.get("body") or "")),
                )
            )
        i, last = sup[-1]
        x = llm.get(i) or {}
        sheets = last.get("term_sheets") or []
        intel.status, intel.sender = last.get("status"), last.get("from")
        intel.signals = dict(last.get("signals") or {})
        intel.claim_results = list(last.get("claim_results") or [])
        intel.missing_fields = list(last.get("missing_fields") or [])
        intel.offers = [{"id": s["term_sheet_id"], "terms": s["terms"], "c": c(s["terms"])} for s in sheets]
        intel.standing = intel.offers[0] if intel.offers else {}
        if len(history) > 1 and history[-1].price is not None and history[-2].price is not None:
            intel.delta = {
                "price": round(history[-1].price - history[-2].price, 2),
                "c": round((history[-1].c or 0) - (history[-2].c or 0), 2),
            }
        intel.unchanged_rounds = unchanged(history)
        intel.walk_risk, intel.walk_signals = walk_risk(history)
        intel.tone = history[-1].tone
        intel.withdraw_language = history[-1].withdraw
        body = last.get("body") or ""

        # (a) offers stated only in prose, priced by code
        found = prose_offers_by_code(body, negotiable)
        for o in x.get("prose_offers") or []:
            if not isinstance(o, dict) or not _appears(o.get("unit_price"), body):
                continue
            t = {"unit_price": float(o["unit_price"])}
            for f in ("payment_days", "effective_date"):
                if o.get(f) is not None and f in negotiable:
                    t[f] = o[f]
            for f, v in (o.get("other_terms") or {}).items():
                if f in negotiable and v is not None:
                    t[f] = v
            found.append({"terms": t, "quote": str(o.get("quote") or "")[:300], "source": "model"})
        base = intel.standing.get("terms") or {}
        c_standing = intel.standing.get("c")
        seen = []
        for o in found:
            stated = o["terms"]
            terms = complete_offer(case, {**std, **base, **stated})
            if any(terms == s for s in seen):
                continue
            seen.append(terms)
            match = next(
                (s["term_sheet_id"] for s in sheets if all(s["terms"].get(k) == v for k, v in stated.items())), None
            )
            cost_ = c(terms)
            intel.prose_offers.append(
                {
                    "terms": terms,
                    "stated": stated,
                    "c": cost_,
                    "in_sheet": match,
                    "beats_standing": bool(cost_ and c_standing and cost_ < c_standing - 0.01),
                    "must_haves_ok": must_haves_ok(case, terms, std),
                    "quote": o["quote"],
                    "source": o["source"],
                }
            )

        # (b) cost drivers -> the weighted impact against the increase asked
        drivers = {}
        for i2, m in sup:  # every mail: a driver named once still counts
            for d in drivers_by_code(m.get("body"), self.series_ids):
                drivers.setdefault((d["series"] or d["name"]).lower(), d)
            for d in (llm.get(i2) or {}).get("cost_drivers") or []:
                if not isinstance(d, dict) or not _appears(d.get("change_pct"), m.get("body") or ""):
                    continue
                share = d.get("cost_share_pct")
                share = float(share) if share is not None and _appears(share, m.get("body") or "") else None
                name = str(d.get("name") or "?")
                series = next((s for s in self.series_ids if s.lower() == name.lower()), None)
                key = (series or name).lower()
                if key not in drivers or (drivers[key]["share_pct"] is None and share is not None):
                    drivers[key] = {
                        "name": name, "series": series, "change_pct": float(d["change_pct"]),
                        "share_pct": share, "quote": str(d.get("quote") or "")[:300], "source": "model",
                    }  # fmt: skip
        for d in drivers.values():
            if d["series"] and (got := cl.index_change(self.package, case, d["series"])):
                d["data_change_pct"] = got[0]
        intel.cost_drivers = list(drivers.values())
        intel.cost_impact_pct = weighted_impact(intel.cost_drivers)
        intel.asked_pct = self._asked_pct(events)
        if intel.cost_impact_pct is not None and intel.asked_pct is not None:
            intel.cost_gap_pct = round(intel.asked_pct - intel.cost_impact_pct, 2)

        # (c) indices they named that the data can speak to
        named = {d["series"] for d in intel.cost_drivers if d["series"]}
        for _, m in sup:
            text = m.get("body") or ""
            named |= {s for s in self.series_ids if re.search(rf"(?<![\w-]){re.escape(s)}(?![\w-])", text)}
        for _, m in sup:
            named |= {s for s in (llm.get(_) or {}).get("named_indices") or [] if s in self.series_ids}
        for series in sorted(named):
            if got := cl.index_change(self.package, case, series):
                chg, a, b = got
                asked = intel.asked_pct
                intel.new_claims.append(
                    cl.Claim(
                        key=f"index:{series}",
                        kind="index",
                        ids=[a, b],
                        figure=chg,
                        favourable=chg <= 1.0 or (asked is not None and chg < asked / 2),
                        sentence=f"{cl.series_name(self.package, series)} changed {chg:+.1f}% "
                        f"from {a.split('@')[1]} to {b.split('@')[1]} ({a}, {b}).",
                        note="an index the supplier named",
                        strength=max(0.0, (asked or 0) - chg) / 4,
                    )
                )

        # (d)-(f) what the model read; code fallbacks where it has nothing
        intel.constraints = [str(s)[:200] for s in x.get("constraints") or []][:6]
        intel.lever_hints = [
            {"field": h.get("field"), "hint": str(h.get("hint") or "")[:200]}
            for h in x.get("lever_hints") or []
            if isinstance(h, dict) and h.get("field") in negotiable
        ][:6]
        style = x.get("relationship_style")
        intel.relationship_style = (
            style if style in ("relationship", "formal", "transactional")
            else "relationship" if RELATIONSHIP.search(" ".join(m.get("body") or "" for _, m in sup)) else None
        )  # fmt: skip
        intel.questions = [str(q)[:300] for q in x.get("questions_to_us") or []] or [
            s for s in writing.sentences(re.sub(r"\s*\n\s*", " ", body)) if s.endswith("?")
        ][:4]
        missing = [str(q)[:200] for q in x.get("missing_info") or []]
        names = " ".join(a.get("name", "") for _, m in sup for a in m.get("attachments") or []).lower()
        if "breakdown" not in names:
            missing.append("cost breakdown")
        missing += [f"{f} (closes on standard terms)" for f in intel.missing_fields]
        intel.missing_info = list(dict.fromkeys(missing))[:8]
        if self.complete is None:
            intel.llm = "off"
        else:
            intel.llm = "done" if i in llm else ("failed" if llm.get(i, None) == {} else "pending")
        intel.updated_at = time.time()
        with self._lock:
            intel.clues = self._intel.clues  # the miner may have written meanwhile
            if i in self._pending and i not in self._llm:
                intel.llm = "pending"
            self._intel = intel

    def _asked_pct(self, events):
        trigger = cl._fact(self.package, self.case, self.case["trigger_doc"]) if self.case.get("trigger_doc") else None
        if trigger and trigger.get("asked_pct") is not None:
            return float(trigger["asked_pct"])
        current = self.case["buyer"].get("current_unit_price")
        opening = next(
            (s["terms"].get("unit_price") for m in events if m.get("from") != "buyer" for s in m.get("term_sheets") or []),
            None,
        )
        if current and opening and self.case.get("type") in ("price_increase", "raw_material") and opening > current:
            return round((opening / current - 1) * 100, 2)
        return None

    # -- the model layer -------------------------------------------------------------------------
    def _extract(self, index, mail):
        t0 = time.monotonic()
        user = "\n\n".join(
            [
                f"NEGOTIABLE FIELDS: {json.dumps(self.case['negotiable'])}; options "
                f"{json.dumps(self.case.get('term_options') or {}, default=str)}",
                f"THEIR TERM SHEETS IN THIS E-MAIL: {json.dumps(mail.get('term_sheets') or [], default=str)}",
                f"E-MAIL from {mail.get('from')} (status {mail.get('status')}):\n{(mail.get('body') or '')[:6000]}",
            ]
        )
        reply = parsed = error = None
        try:
            reply = self.complete(ANALYST_SYSTEM, user)
            parsed = writing.parse(reply)
        except Exception as e:
            error = f"{type(e).__name__}: {e}"
            parsed = {}
        finally:
            if self.rec:
                self.rec.llm(
                    kind="analyst", supplier_id=self.sid, mail=index, seconds=round(time.monotonic() - t0, 2),
                    prompt=user, reply=reply, parsed=parsed, error=error,
                )  # fmt: skip
        with self._lock:
            self._llm[index] = parsed if isinstance(parsed, dict) else {}
            self._pending.pop(index, None)
        self._rebuild()
        return parsed

    # -- between mails ---------------------------------------------------------------------------
    def _mine(self):
        """Clues in the dossier for the open gap: notes, letters, news, quote remarks that mention the
        drivers, the levers or the supplier's situation, best first."""
        intel = self.snapshot()
        focus = set(CLUE_WORDS) | {d["name"].lower() for d in intel.cost_drivers}
        focus |= {h["field"].replace("_", " ").split()[0] for h in intel.lever_hints if h.get("field")}
        rows = []
        for r in self.dossier.get("correspondence") or []:
            rows.append((r.get("id"), r.get("text") or ""))
        for r in self.dossier.get("news") or []:
            rows.append((r.get("id"), f"{r.get('headline') or ''}. {r.get('body') or ''}"))
        for r in self.dossier.get("quotes") or []:
            if r.get("remarks"):
                rows.append((r.get("id"), str(r["remarks"])))
        for r in self.dossier.get("history") or []:
            if r.get("note"):
                rows.append((f"history {r.get('date')}", str(r["note"])))
        found = []
        for src, text in rows:
            for s in writing.sentences(text):
                hits = sum(w in s.lower() for w in focus)
                if hits:
                    found.append((hits, src, s.strip()[:240]))
        found.sort(key=lambda h: -h[0])
        clues, seen = [], set()
        for _, src, s in found:
            if s not in seen:
                seen.add(s)
                clues.append({"source": src, "text": s})
            if len(clues) == 8:
                break
        with self._lock:
            self._intel.clues = clues


def bind_rec(rec, fn):
    """`fn` that logs into `rec`'s case from a worker thread."""

    def run(*a, **kw):
        with runlog.bind(rec):
            return fn(*a, **kw)

    return run

"""The dual agent: a negotiator on the critical path, an analyst per supplier thread beside it.

  Negotiator  answers every supplier e-mail well inside the 60 seconds: code decides close / counter
              (`strategy`, `cost`), a concession guard caps every step at RECIPROCITY × the
              supplier's last step, and the e-mail is written in the wording style of one tactic
              (`tactics`) picked from the analyst's latest view - the tactic never touches a number.
  Analyst     one per supplier thread (`intel.Analyst`), in worker threads: structured signals from
              the API at once, a model extraction of the body in the background, cost arithmetic
              and walk risk in code, dossier mining between e-mails. The negotiator reads whatever
              snapshot is ready after a short grace period.

Clock (from case open): no new counter-offer after NO_NEW_COUNTER_AT, closed by FORCE_CLOSE_AT.
Closing accepts the standing term sheet with the lowest C that beats the alternative and keeps the
must-haves (standard terms from the quote PDF fill what it leaves out), else walks away.

Every model call has a timeout and a code fallback: without a model the agent still negotiates,
with code-written wording per tactic.
"""

import json
import logging
import math
import os
import re
import time
from concurrent.futures import ThreadPoolExecutor

from .. import claims as cl
from .. import dossier, runlog, strategy, tactics, writing
from ..cost import closing_terms, complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..intel import Analyst
from ..play import closing_move, latest, live_threads, moves_left, offers
from .buyer import GOAL_WORDS, PROFILE_SYSTEM
from .naive import NaiveAgent

log = logging.getLogger("arena")

NO_NEW_COUNTER_AT = 360.0  # s after case open: no new counter-offers
FORCE_CLOSE_AT = 420.0  # s after case open: closed at the latest
WALK_RISK_CLOSE = 0.7
ANALYST_GRACE_S = 12.0  # how long the negotiator waits for the analyst's model layer
WRITE_TIMEOUT_S = 25.0  # the writer model's share of the 60 seconds
DEFAULT_REPLY_S = 45.0  # a supplier round trip before we have measured one
ROUND_MARGIN_S = 10.0
PROFILE_TIMEOUT_S = 90.0
NEGOTIATOR_MODEL = ANALYST_MODEL = "claude-sonnet-5-5"
PART_RE = re.compile(r"\bpart:\d+\b")
QUESTIONS = {
    "quality": "Could you send us the 8D report with root cause and containment for the recent complaints?",
    "capacity": "Could you send a delivery schedule with the monthly quantities you can commit to?",
    "rfq": "What is the shortest lead time you could commit to, and is there a cheaper design or material variant?",
    "renewal": "Which volume or contract length would let you improve the price further?",
    "bundling": "Which further parts or volumes would make a bundle more attractive for you?",
    "raw_material": "Which base month and deadband would you consider fair for an index clause?",
}
BREAKDOWN_Q = "Could you share a cost breakdown for this part - material, conversion, overhead?"


def llms_from_env():
    """(negotiator, analyst, prep) completions on the Anthropic provider, or None each when no
    credentials are set (the agent then writes code-only). LLM_MODEL / LLM_ANALYST_MODEL /
    LLM_PREP_MODEL pick the models; ARENA_DUAL_LLM=0 switches the models off."""
    from .llm import llm_from_env

    if os.environ.get("ARENA_DUAL_LLM", "1").lower() in ("0", "false", "no", "off"):
        return None, None, None
    if not (os.environ.get("ANTHROPIC_API_KEY") or os.environ.get("ANTHROPIC_AUTH_TOKEN")):
        log.warning("dual agent: no Anthropic credentials - negotiating with code-written e-mails")
        return None, None, None
    env = os.environ.get("LLM_MODEL") or ""
    negotiator = env if env.startswith("claude") else NEGOTIATOR_MODEL
    analyst = os.environ.get("LLM_ANALYST_MODEL") or ANALYST_MODEL
    prep = os.environ.get("LLM_PREP_MODEL")
    return (
        llm_from_env(negotiator, timeout=WRITE_TIMEOUT_S, provider="anthropic", retries=0),
        llm_from_env(analyst, timeout=ANALYST_GRACE_S + 15, provider="anthropic", retries=0),
        llm_from_env(prep, timeout=PROFILE_TIMEOUT_S, provider="anthropic") if prep else None,
    )


def concession_guard(prev, proposed, their_step, scale):
    """(target, our step) in C: never further toward them than RECIPROCITY × their last step, never
    back from what we offered, and no token steps (below MIN_STEP of `scale` we hold)."""
    allowed = strategy.RECIPROCITY * max(their_step, 0.0)
    ours = min(max(proposed - prev, 0.0), allowed)
    if ours < strategy.MIN_STEP * scale:
        ours = 0.0
    return prev + ours, ours


def weighted_sentence(intel):
    """The cost-share arithmetic by the supplier's own figures, or None."""
    shared = [d for d in intel.cost_drivers if d.get("share_pct") is not None]
    if not shared or intel.cost_impact_pct is None or intel.asked_pct is None or (intel.cost_gap_pct or 0) <= 1.0:
        return None
    items = ", ".join(f"{d['series'] or d['name']} {d['change_pct']:+.1f}% at {d['share_pct']:g}% of your cost" for d in shared)
    return (
        f"By the figures you gave us - {items} - the weighted effect on the price is about "
        f"{intel.cost_impact_pct:+.1f}%, not the {intel.asked_pct:g}% you ask for."
    )


class DualAgent:
    def __init__(self, complete=None, package=None, analyst_complete=None, prep_complete=None, clock=time.monotonic):
        self.complete, self.package = complete, package
        self.analyst_complete, self.prep_complete = analyst_complete, prep_complete
        self.clock = clock
        self.fallback = NaiveAgent()
        self.case_id = None

    # --- before the clock -------------------------------------------------------------------------
    def prime(self, case):
        """Dossiers, our own context and (optionally) a profile per supplier. Safe to call again."""
        if case["case_id"] == self.case_id:
            return
        self.case_id, self.case = case["case_id"], case
        self.dossiers, self.profiles, self.plans, self.analysts = {}, {}, {}, {}
        self.ledger, self.sent_claims, self.said = cl.Ledger(), {}, {}
        self.last_sheets, self.tactic_log, self.latencies = {}, {}, []
        self.t_open = self.last_sent_at = None
        self.pool = ThreadPoolExecutor(max_workers=4 * len(case["suppliers"]) + 2, thread_name_prefix="analyst")
        self.company = self._company_context()
        self.context = self._case_context(case)
        for sid in case["suppliers"]:
            self._gather(case, sid)
        if self.prep_complete is not None:
            rec = runlog.current()
            futures = {sid: self.pool.submit(self._profile, case, sid, rec) for sid in case["suppliers"]}
            deadline = time.monotonic() + PROFILE_TIMEOUT_S
            for sid, f in futures.items():
                try:
                    self.profiles[sid] = f.result(timeout=max(0.1, deadline - time.monotonic()))
                except Exception as e:
                    log.warning("profile for %s failed (%s) - using defaults", sid, e)

    def _gather(self, case, sid):
        if sid not in self.dossiers:
            self.dossiers[sid] = dossier.gather(self.package, case, sid)
            self.plans[sid] = strategy.Plan()
            self.profiles.setdefault(sid, self._default_profile(case, sid))

    def _company_context(self):
        root = getattr(self.package, "root", None)
        for path in [root / "company.md"] if root else []:
            if path.is_file():
                return path.read_text(encoding="utf-8")[:3000]
        return ""

    @staticmethod
    def _case_context(case):
        b = case["buyer"]
        keep = ("need_per_year", "horizon_years", "current_unit_price", "category_goal", "reference_payment_days",
                "need_lead_time_days", "must_haves", "alternative")  # fmt: skip
        return {"title": case.get("title"), "type": case.get("type"), "briefing": case.get("briefing"),
                **{k: b.get(k) for k in keep}}  # fmt: skip

    def _default_profile(self, case, sid):
        d = self.dossiers.get(sid, {})
        levers = (["payment_days"] if d.get("cash_signals") else []) + strategy.TYPE_LEVERS.get(case.get("type"), [])
        return {"levers": list(dict.fromkeys(levers)), "cash_short": bool(d.get("cash_signals")), "claim_ranking": []}

    def _profile(self, case, sid, rec):
        args = cl.candidates(self.package, case, sid)
        user = (
            f"CASE\n{json.dumps(self.context, ensure_ascii=False, default=str)}\n\nOUR COMPANY\n{self.company}\n\n"
            f"{dossier.render(self.dossiers[sid])}\n\nARGUMENTS ([key] sentence - note)\n"
            + "\n".join(f"[{a.key}] {a.sentence} - {a.note}" for a in args)
        )
        t0, reply, parsed, error = time.monotonic(), None, None, None
        try:
            reply = self.prep_complete(PROFILE_SYSTEM, user)
            parsed = writing.parse(reply)
        except Exception as e:
            error = f"{type(e).__name__}: {e}"
            raise
        finally:
            if rec:
                rec.llm(kind="profile", supplier_id=sid, seconds=round(time.monotonic() - t0, 2), prompt=user,
                        reply=reply, parsed=parsed, error=error)  # fmt: skip
        profile = {**self._default_profile(case, sid), **{k: v for k, v in parsed.items() if v not in (None, "")}}
        fields = {f: f for f in case["negotiable"] if f != "unit_price"}
        profile["levers"] = list(dict.fromkeys(f for t in profile.get("levers") or [] if (f := writing.match_key(t, fields))))
        keys = {a.key: a.key for a in args}
        profile["claim_ranking"] = [k for t in profile.get("claim_ranking") or [] if (k := writing.match_key(t, keys))]
        profile["cash_short"] = bool(profile.get("cash_short")) or bool(self.dossiers[sid].get("cash_signals"))
        return profile

    # --- every round ------------------------------------------------------------------------------
    def decide(self, case, threads):
        return self.decide_all(case, threads)[0]

    def decide_all(self, case, threads):
        rec = runlog.current()
        t0 = self.clock()
        try:
            self.prime(case)
            if self.t_open is None:
                self.t_open = t0
            elif self.last_sent_at is not None:
                self.latencies.append(t0 - self.last_sent_at)
            moves = self._round(case, threads, rec, t0)
        except Exception as e:
            log.exception("dual agent failed (%s) - falling back", e)
            if rec:
                rec.flag = "fell back"
            late = self.t_open is not None and t0 - self.t_open >= NO_NEW_COUNTER_AT
            moves = [closing_move(case, threads) if late else self.fallback.decide(case, threads)]
        if not any(m["message"].get("action") for m in moves):
            self.last_sent_at = self.clock()
        return moves

    def _analyst(self, case, sid, rec):
        if sid not in self.analysts:
            self.analysts[sid] = Analyst(case, sid, self.package, self.dossiers.get(sid), self.analyst_complete,
                                         self.pool, rec)  # fmt: skip
        return self.analysts[sid]

    def _open_case(self, case, threads):
        """From the first mails: every supplier and part named, each with its dossier."""
        parts = set(case.get("parts", []))
        for events in threads.values():
            for m in events:
                parts |= set(PART_RE.findall(m.get("body") or ""))
        if parts - set(case.get("parts", [])):
            log.info("parts named in the mails beyond the case file: %s", sorted(parts - set(case["parts"])))
        for sid in threads:
            self._gather(case, sid)

    def _state(self, case, sid, events, intel):
        std = standard_terms(events)
        opening = next((s["terms"] for m in events if m.get("from") != "buyer" for s in m.get("term_sheets") or []), None)
        est = strategy.estimate(case, sid, self.package, events, opening,
                                cash_short=self.profiles.get(sid, {}).get("cash_short", False))  # fmt: skip
        choices = [(i, t) for i, t in offers(events) if t.get("unit_price")]
        sheet_id, terms = min(
            choices, key=lambda c: (not must_haves_ok(case, c[1], std), strategy.cost(case, c[1], std, est)),
            default=(None, {}),
        )  # fmt: skip
        return {
            "sid": sid, "events": events, "sheet_id": sheet_id, "terms": terms, "std": std, "est": est,
            "c_now": strategy.cost(case, terms, std, est) if sheet_id else math.inf,
            "status": latest(events).get("status"), "left": moves_left(case, events), "intel": intel,
        }  # fmt: skip

    def _round(self, case, threads, rec, t0):
        elapsed = t0 - self.t_open
        live = live_threads(threads)
        if elapsed == 0:
            self._open_case(case, threads)
        for sid in live:
            self._analyst(case, sid, rec).observe(threads[sid])
        if self.analyst_complete is not None:  # the model layer gets a short grace, then we go with what is ready
            deadline = time.monotonic() + ANALYST_GRACE_S
            for sid in live:
                self.analysts[sid].wait(deadline - time.monotonic())
        intel = {sid: self.analysts[sid].snapshot() for sid in live}
        states = {s: self._state(case, s, threads[s], intel[s]) for s in live}
        quoting = {s: st for s, st in states.items() if st["sheet_id"] and st["terms"].get("unit_price")}
        record = {"elapsed_s": round(elapsed, 1), "intel": {s: i.to_log() for s, i in intel.items()},
                  "received": {s: [{**o, "c_est": self._c(case, o["terms"], states[s])} for o in i.offers]
                               for s, i in intel.items()}}  # fmt: skip
        if not quoting:
            return self._finish(rec, record, [self._walk(live[0])], "no supplier quotes a price")
        for s in quoting:
            self._feedback(s, threads[s])
        rfq = len(case["suppliers"]) > 1
        for s, st in quoting.items():
            self._target(case, st, quoting, rfq)
        record["targets"] = {s: round(st["target"], 2) for s, st in quoting.items()}

        reason = self._close_reason(case, quoting, rfq, elapsed)
        if reason:
            return self._finish(rec, record, [self._close(case, threads, quoting)], reason)
        if elapsed >= NO_NEW_COUNTER_AT:
            return self._late(case, threads, quoting, rec, record, elapsed)

        talk = [s for s, st in quoting.items() if st["left"] > 0 and st["status"] != "final_offer"]
        best_c = min(st["c_now"] for st in quoting.values())
        if rfq and len(talk) > 2:
            talk = [s for s in talk if quoting[s]["c_now"] <= best_c * 1.25 or len(self.plans[s].targets) < 2]
        if not talk:
            return self._finish(rec, record, [self._close(case, threads, quoting)], "no thread left to talk to")
        moves = [self._offer(case, quoting[s], quoting, rfq, elapsed) for s in talk]
        return self._finish(rec, record, self._write_all(case, threads, moves, rec), None, moves)

    # --- the numbers --------------------------------------------------------------------------------
    def _c(self, case, terms, st):
        try:
            return round(strategy.cost(case, terms, st["std"], st["est"]), 2)
        except Exception:
            return None

    def _feedback(self, sid, events):
        for r in latest(events).get("claim_results") or []:
            sent = self.sent_claims.get(sid, [])
            if r.get("index") is not None and r["index"] < len(sent):
                self.ledger.results[sent[r["index"]].key] = r.get("result")
                if r.get("result") == "contradicted":
                    log.warning("%s: argument %s was contradicted", sid, sent[r["index"]].key)

    def _target(self, case, st, quoting, rfq):
        """Where our next offer lands, in C - the concession curve, capped by the guard."""
        sid, plan = st["sid"], self.plans[st["sid"]]
        price = st["terms"]["unit_price"]
        ref = strategy.mutual_combo(case, st["terms"], st["std"], st["est"])
        c_ref = min(strategy.cost(case, {**ref, "unit_price": price}, st["std"], st["est"]), st["c_now"])
        replies = sum(m.get("from") != "buyer" for m in st["events"])
        if replies > plan.replies:
            plan.their_costs.append(c_ref)
            plan.replies = replies
        if plan.anchor is None:
            rivals = [o["terms"]["unit_price"] for s2, o in quoting.items() if s2 != sid and rfq]
            p = strategy.anchor_price(case, st["terms"], st["est"], min([price, *rivals]))
            plan.anchor = min(strategy.cost(case, {**ref, "unit_price": p}, st["std"], st["est"]), c_ref)
        k = len(plan.targets)
        horizon = 5 if rfq else strategy.ROUND_HORIZON
        proposed = plan.anchor + strategy.concession(k, horizon) * (c_ref - plan.anchor)
        step = plan.their_costs[-2] - plan.their_costs[-1] if len(plan.their_costs) > 1 else 0.0
        st["their_step"], st["moving"] = step, step > strategy.MIN_STEP * c_ref
        target, st["our_step"] = (concession_guard(plan.targets[-1], proposed, step, c_ref) if k else (proposed, None))
        others = [o["c_now"] for s2, o in quoting.items() if s2 != sid]
        if rfq and others:
            target = max(plan.anchor, min(target, min(others) * 0.99))  # beat the best rival
        target = min(target, strategy.c_alternative(case) * 0.995)
        st["meets"] = st["c_now"] <= target * 1.002 or (k and st["c_now"] <= plan.targets[-1] * 1.001)
        if st["meets"] and st["moving"] and st["left"] > 3:
            st["meets"] = False  # still conceding: their offer is not their last word - ask once more
            target = min(target, st["c_now"] - 0.5 * step)
        st["target"] = min(target, st["c_now"] * (1 - 1e-4))  # never their current standing offer
        st["gap_pct"] = (st["c_now"] - st["target"]) / st["target"] * 100 if st["target"] > 0 else None

    def _acceptable(self, case, terms, std, est):
        c_alt = strategy.c_alternative(case)
        return (must_haves_ok(case, terms, std) and total_cost(case, terms, std) < c_alt
                and strategy.cost(case, terms, std, est) < c_alt)  # fmt: skip

    def _best_offer(self, case, threads, quoting):
        """(rank C, sid, sheet_id) of the best acceptable sheet across all live threads, or None."""
        best = None
        for sid in live_threads(threads):
            std = standard_terms(threads[sid])
            est = quoting.get(sid, {}).get("est")
            for sheet_id, terms in offers(threads[sid]):
                if terms.get("unit_price") and self._acceptable(case, terms, std, est):
                    c = strategy.cost(case, terms, std, est)
                    best = min(best or (c, sid, sheet_id), (c, sid, sheet_id))
        return best

    def _close_reason(self, case, quoting, rfq, elapsed):
        if elapsed >= FORCE_CLOSE_AT:
            return f"force close: {elapsed:.0f}s since case open"
        best_sid = min(quoting, key=lambda s: quoting[s]["c_now"])

        def fires(pred):  # single thread: that thread; an RFQ: the best thread, or every thread
            return pred(quoting[best_sid]) or (rfq and all(pred(st) for st in quoting.values()))

        if fires(lambda st: st["status"] == "agreed"):
            return "the supplier agreed to our terms"
        if fires(lambda st: st["status"] == "final_offer"):
            return "final offer"
        if fires(lambda st: st["intel"].walk_risk >= WALK_RISK_CLOSE):
            i = quoting[best_sid]["intel"]
            return f"walk risk {i.walk_risk:.2f} ({', '.join(i.walk_signals)})"
        if fires(lambda st: st["left"] <= 1):
            return "rounds left <= 1"
        if fires(lambda st: st["meets"]):
            return "their offer meets our target"
        if fires(lambda st: st["intel"].unchanged_rounds >= 2 and st.get("our_step") == 0):
            return "deadlock: neither side moved for two rounds"
        if elapsed + self._round_time() > FORCE_CLOSE_AT:
            return f"no time for another round ({elapsed:.0f}s + {self._round_time():.0f}s > {FORCE_CLOSE_AT:.0f}s)"
        return None

    def _round_time(self):
        return (max(self.latencies) if self.latencies else DEFAULT_REPLY_S) + ROUND_MARGIN_S

    def _close(self, case, threads, quoting):
        best = self._best_offer(case, threads, quoting)
        if best is None:
            return self._walk(live_threads(threads)[0])
        c, sid, sheet_id = best
        std = standard_terms(threads[sid])
        terms = dict(next(t for i, t in offers(threads[sid]) if i == sheet_id))
        self._closing = {"supplier_id": sid, "sheet_id": sheet_id, "c_est": round(c, 2),
                         "c": total_cost(case, terms, std), "closing_terms": closing_terms(case, terms, std),
                         "missing_fields": latest(threads[sid]).get("missing_fields") or [],
                         "c_alternative": strategy.c_alternative(case)}  # fmt: skip
        return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}

    def _walk(self, sid):
        self._closing = {"walk_away": True, "c_alternative": strategy.c_alternative(self.case)}
        return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}

    def _late(self, case, threads, quoting, rec, record, elapsed):
        """After NO_NEW_COUNTER_AT: no new counter. Lock in a better prose offer if a round still fits,
        repeat our last offer only when nothing on the table is acceptable (nothing to lose), else close."""
        fits = elapsed + self._round_time() <= FORCE_CLOSE_AT
        best = self._best_offer(case, threads, quoting)
        locks = [(lk["c_est"], s, lk) for s, st in quoting.items() if (lk := self._lock_in(case, st))]
        lock = min(locks, key=lambda x: x[0]) if locks else None
        if fits and lock and (best is None or lock[0] < best[0] - 0.01):
            _, sid, lk = lock
            move = self._move(case, quoting[sid], [("their prose offer", lk["terms"])], quoting, "appreciation_close",
                              "lock in the offer they stated in prose", hold=False)  # fmt: skip
            return self._finish(rec, record, self._write_all(case, threads, [move], rec), None, [move])
        if fits and best is None:
            moves = [self._move(case, quoting[s], self.last_sheets[s], quoting, "firm_disappointment",
                                "nothing acceptable yet: repeat our last offer", hold=True)
                     for s in quoting if self.last_sheets.get(s) and quoting[s]["left"] > 1]  # fmt: skip
            if moves:
                return self._finish(rec, record, self._write_all(case, threads, moves, rec), None, moves)
        return self._finish(rec, record, [self._close(case, threads, quoting)], f"no new counters after {elapsed:.0f}s")

    def _lock_in(self, case, st):
        """The supplier's best offer stated only in prose, if it beats its standing sheet: {terms, c_est}."""
        best = None
        for po in st["intel"].prose_offers:
            if po.get("in_sheet") or not po.get("must_haves_ok"):
                continue
            terms = complete_offer(case, po["terms"])
            c = self._c(case, terms, st)
            if c is not None and c < st["c_now"] - 0.01 and self._acceptable(case, terms, st["std"], st["est"]):
                if best is None or c < best["c_est"]:
                    best = {"terms": terms, "c_est": c, "quote": po.get("quote")}
        return best

    def _offer(self, case, st, quoting, rfq, elapsed):
        sid, plan, profile = st["sid"], self.plans[st["sid"]], self.profiles.get(st["sid"], {})
        levers = list(dict.fromkeys(profile.get("levers", []) + strategy.TYPE_LEVERS.get(case.get("type"), [])))
        est, price = st["est"], st["terms"]["unit_price"]
        floor = est.full_cost * 0.97 if est.full_cost and est.source != strategy.OPENING_GUESS else price * 0.6
        held = st.get("our_step") is not None and st["our_step"] <= 0
        sheets = []
        if held and self.last_sheets.get(sid):
            sheets = list(self.last_sheets[sid])  # we hold: the same offer again, word for word
        else:
            sheets = strategy.sheets(case, st["std"], est, st["terms"], st["target"], levers, floor)
        sheets = self._guard_sheets(case, st, sheets)
        if not sheets:
            combo = strategy.base_combo(case, st["terms"], st["std"])
            p = strategy.price_at(case, combo, st["std"], est, st["target"], max(0.01, floor), price)
            t = complete_offer(case, {**combo, "unit_price": p}) if p else None
            sheets = self._guard_sheets(case, st, [("their terms", t)] if t else [])
        if not sheets and self.last_sheets.get(sid):
            sheets = list(self.last_sheets[sid])
        lock = self._lock_in(case, st)
        pressure = st["left"] <= 2 or st["intel"].walk_risk >= 0.5 or elapsed + 2 * self._round_time() > NO_NEW_COUNTER_AT
        if lock and (pressure or lock["c_est"] <= st["target"] * 1.0005):
            sheets = [("their prose offer", lock["terms"]), *[s for s in sheets if s[1] != lock["terms"]]][:3]
        plan.targets.append(st["target"])
        name, reason = self._pick(case, st, quoting, rfq, sheets)
        return self._move(case, st, sheets, quoting, name, reason, hold=held, lock=lock)

    def _guard_sheets(self, case, st, sheets):
        """Code's last word on the numbers: every sheet costs us at most the guarded target, is better
        for us than their standing offer, is not one of their sheets, and keeps the must-haves."""
        theirs = [complete_offer(case, {**st["std"], **t}) for _, t in offers(st["events"])]
        out = []
        for label, t in sheets:
            c = self._c(case, t, st)
            if c is None or c > st["target"] + max(0.01, 1e-5 * st["target"]) or c >= st["c_now"]:
                continue
            if t in theirs or not must_haves_ok(case, t, st["std"]):
                continue
            out.append((label, t))
        return out

    def _pick(self, case, st, quoting, rfq, sheets):
        sid, i = st["sid"], st["intel"]
        rivals = {o["sheet_id"]: o["terms"]["unit_price"] for s2, o in quoting.items() if s2 != sid}
        args = self._args(case, st, rivals)
        ctx = {
            "first": not self.plans[sid].targets[:-1],
            "rfq": rfq,
            "rival_cheaper": any(o["c_now"] < st["c_now"] for s2, o in quoting.items() if s2 != sid)
            or any(a.kind == "rival" for a in args),
            "cash_short": self.profiles.get(sid, {}).get("cash_short", False),
            "gap_pct": st.get("gap_pct"),
            "cost_gap_pct": i.cost_gap_pct,
            "data_claims": sum(1 for a in args if a.ids and a.kind != "news"),
            "relationship": i.relationship_style == "relationship",
            "asked_for_terms": bool(i.lever_hints),
        }
        return tactics.pick(i, ctx)

    def _args(self, case, st, rivals):
        sid, profile = st["sid"], self.profiles.get(st["sid"], {})
        args = cl.candidates(self.package, case, sid, their_price=st["terms"]["unit_price"], rivals=rivals)
        keys = {a.key for a in args}
        args += [c for c in st["intel"].new_claims if c.key not in keys]
        ranking = profile.get("claim_ranking") or []
        for a in args:
            if a.key in ranking and a.kind == "news":
                a.favourable = True
        args = [a for a in cl.usable(args, self.ledger, sid) if self.ledger.results.get(a.key) != "contradicted"]
        args.sort(key=lambda a: (ranking.index(a.key) if a.key in ranking else len(ranking), -a.strength))
        return args

    def _move(self, case, st, sheets, quoting, tactic, reason, hold, lock=None):
        sid = st["sid"]
        rivals = {o["sheet_id"]: o["terms"]["unit_price"] for s2, o in quoting.items() if s2 != sid}
        self.last_sheets[sid] = list(sheets)
        self.tactic_log.setdefault(sid, []).append(tactic)
        return {"st": st, "sheets": sheets, "args": self._args(case, st, rivals), "tactic": tactic,
                "reason": reason, "hold": hold, "lock": lock}  # fmt: skip

    # --- the e-mails --------------------------------------------------------------------------------
    def _write_all(self, case, threads, moves, rec):
        futures = [self.pool.submit(self._write, case, threads, m, rec) for m in moves]
        deadline, out = time.monotonic() + WRITE_TIMEOUT_S + 2, []
        for m, f in zip(moves, futures, strict=True):
            try:
                out.append(f.result(timeout=max(0.1, deadline - time.monotonic())))
            except Exception as e:  # late or broken: code writes the e-mail and keeps the clock
                log.warning("writing to %s failed (%s) - code e-mail", m["st"]["sid"], e)
                out.append(self._compose(case, threads, m, self._code_parts(case, m), rec, error=f"{type(e).__name__}: {e}"))
        return out

    def _code_parts(self, case, move):
        t = tactics.TACTICS[move["tactic"]]
        return {"salutation": "", "opening": t.opening, "claims": None, "bridge": t.bridge,
                "question": (self._questions(case, move["st"]["events"]) or [""])[0], "closing": t.closing,
                "fallback": True}  # fmt: skip

    def _questions(self, case, events):
        ours = " ".join(m.get("body", "") for m in events if m.get("from") == "buyer").lower()
        got = " ".join(a.get("name", "") for m in events for a in m.get("attachments") or []).lower()
        qs = [BREAKDOWN_Q] if "breakdown" not in ours and "breakdown" not in got else []
        if (q := QUESTIONS.get(case.get("type"))) and q[:40].lower() not in ours:
            qs.append(q)
        return qs

    def _write(self, case, threads, move, rec):
        if self.complete is None:
            return self._compose(case, threads, move, self._code_parts(case, move), rec)
        st, events = move["st"], threads[move["st"]["sid"]]
        last, ours, i = latest(events), [m for m in events if m.get("from") == "buyer"], st["intel"]
        t = tactics.TACTICS[move["tactic"]]
        labelled = [(label, strategy.summarise_terms(case, s)) for label, s in move["sheets"]]
        view = {"status": i.status, "tone": i.tone, "relationship_style": i.relationship_style,
                "constraints": i.constraints, "lever_hints": i.lever_hints, "their_questions": i.questions,
                "we_still_miss": i.missing_info, "clues_from_our_files": [c["text"] for c in i.clues[:4]]}  # fmt: skip
        stance = ("This is our first reply to their quote: we open ambitiously; give reasons, not apologies."
                  if not ours else "We HOLD our last offer: say so plainly and give one reason." if move["hold"]
                  else "We make a step: make clear it costs us and that we expect a step back.")  # fmt: skip
        if move.get("lock") and any(label == "their prose offer" for label, _ in move["sheets"]):
            stance += " One option takes up the offer they stated in their own e-mail; name it as theirs."
        user = "\n\n".join(x for x in [
            f"CASE: {case['title']} ({case.get('type')}). Supplier: {self._company(st['sid'], events)}. "
            f"Our stance: {GOAL_WORDS.get(case['buyer'].get('category_goal', 'routine'))}.",
            f"TACTIC: {t.name} - {t.style}",
            f"WHAT OUR ANALYST SEES: {json.dumps(view, ensure_ascii=False, default=str)}",
            f"THEIR LAST E-MAIL (from {last.get('from')}, status {last.get('status')}):\n{(last.get('body') or '')[:2500]}",
            "OUR EARLIER E-MAILS:\n" + "\n---\n".join((m.get("body") or "")[:600] for m in ours[-2:]) if ours else "",
            f"THE MOVE: {stance} The options (code inserts them after your bridge): "
            + "; ".join(f"[{label}] {text}" for label, text in labelled),
            "ARGUMENTS ([key] sentence - note; answer with the keys only):\n"
            + ("\n".join(f"[{a.key}] {a.sentence} - {a.note}" for a in move["args"][:6]) or "(none)"),
            "QUESTIONS (pick one or none):\n" + "\n".join(self._questions(case, events)),
        ] if x)  # fmt: skip
        t0, reply, parsed, error = time.monotonic(), None, None, None
        try:
            reply = self.complete(writing.SYSTEM + f"\n\nWording style for this e-mail ({t.name}): {t.style}", user)
            parsed = writing.parse(reply)
        except Exception as e:
            error = f"{type(e).__name__}: {e}"
            parsed = self._code_parts(case, move)
        return self._compose(case, threads, move, parsed, rec, prompt=user, reply=reply, error=error,
                             seconds=time.monotonic() - t0)  # fmt: skip

    def _code_sentences(self, case, move):
        """Sentences code writes in full: the cost-share arithmetic and our payment-term position."""
        st, sid = move["st"], move["st"]["sid"]
        said = self.said.setdefault(sid, set())
        first = not any(m.get("from") == "buyer" for m in st["events"])
        analysis, position = [], []
        if (s := weighted_sentence(st["intel"])) and (first or (move["tactic"] == "data_argument" and "gap" not in said)):
            analysis.append(s)
            said.add("gap")
        ref = case["buyer"].get("reference_payment_days")
        if "payment_days" in case["negotiable"] and ref and (first or move["tactic"] == "lever_trade") and "pay" not in said:
            position.append(f"Our standard payment term is {ref} days net: paying earlier ties up our working "
                            "capital, so an option with faster payment carries a lower price.")  # fmt: skip
            fast = [(n, t["payment_days"]) for n, (_, t) in enumerate(move["sheets"]) if t.get("payment_days", ref) < ref]
            if fast and len(move["sheets"]) > 1:
                n, d = min(fast, key=lambda x: x[1])
                position.append(f"If quick payment matters to you, Option {'ABC'[n]} pays in {d} days.")
            said.add("pay")
        if move["hold"]:
            position.append("We keep our offer as it stands.")
        elif move.get("lock") and any(label == "their prose offer" for label, _ in move["sheets"]):
            position.append("Option A takes up the offer you described in your e-mail.")
        return analysis, position

    def _pick_claims(self, parts, move):
        by_key = {a.key: a for a in move["args"]}
        if not parts.get("fallback"):
            keys = parts.get("claims") or []
        else:  # code picks: the data tactics carry more arguments
            n = 2 if move["tactic"] in ("data_argument", "competitive_pressure") else 1
            kinds = ("rival",) if move["tactic"] == "competitive_pressure" else None
            keys = [a.key for a in move["args"] if a.ids and a.kind != "news" and (not kinds or a.kind in kinds)][:n]
        picked = []
        for k in keys:
            if (c := writing.match_key(k, by_key)) and c not in picked and len(picked) < 3:
                picked.append(c)
        return picked

    def _compose(self, case, threads, move, parts, rec, prompt=None, reply=None, error=None, seconds=0.0):
        st = move["st"]
        sid, events = st["sid"], threads[st["sid"]]
        labelled = [(label, strategy.summarise_terms(case, t)) for label, t in move["sheets"]]
        company = self._company(sid, events)
        material = self._material(case, events)
        clauses = " ".join(r.get("text", "") for r in self.dossiers.get(sid, {}).get("clauses", []))
        picked = self._pick_claims(parts, move)
        analysis, position = self._code_sentences(case, move)
        numbers = writing.allowed(material, clauses, *(a.sentence for a in move["args"]), *(t for _, t in labelled),
                                  *analysis, *position)  # fmt: skip
        dropped = []
        clean = {k: writing.lint(parts.get(k), numbers, dropped) for k in ("opening", "bridge", "question", "closing")}
        args = " ".join(c.sentence + "".join(" " + e for e in c.extra) for c in picked)
        body = "\n\n".join(p for p in [
            writing.salutation(parts.get("salutation"), company, material),
            clean["opening"],
            " ".join(x for x in (*analysis, args) if x),
            " ".join(x for x in (clean["bridge"], *position) if x),
            writing.options_paragraph(labelled),
            clean["question"],
            clean["closing"],
            writing.SIGNATURE,
        ] if p)  # fmt: skip
        for a in picked:
            self.ledger.use(a, sid)
        self.sent_claims[sid] = [a for a in picked if a.ids]
        refs = [i for a in picked for i in a.ids][:20]
        msg = {"subject": writing.subject(case, events), "body": body[:8000],
               "term_sheets": [{"terms": t} for _, t in move["sheets"]]}  # fmt: skip
        if refs:
            msg["refs"] = refs
        move["sent_sheets"] = [{"label": label, "terms": t, "c_est": self._c(case, t, st),
                                "c": total_cost(case, t, st["std"])} for label, t in move["sheets"]]  # fmt: skip
        if rec:
            rec.llm(kind="write", supplier_id=sid, tactic=move["tactic"], seconds=round(seconds, 2), prompt=prompt,
                    reply=reply, parsed=parts, error=error, dropped=dropped, sent=msg)  # fmt: skip
        return {"supplier_id": sid, "message": msg}

    def _material(self, case, events):
        parts = [m.get("body", "") for m in events if m.get("from") != "buyer"]
        if self.package and case.get("trigger_doc"):
            try:
                parts.append(self.package.document(case["trigger_doc"]))
            except (FileNotFoundError, ValueError, KeyError):
                pass
        return "\n".join(parts)

    def _company(self, sid, events):
        if name := (self.dossiers.get(sid, {}).get("supplier") or [{}])[0].get("name"):
            return name
        for m in events:
            if m.get("from") != "buyer" and (found := re.search(r"Quote from (.+?):", m.get("subject") or "")):
                return found.group(1).strip()
        return "your team"

    # --- the log ------------------------------------------------------------------------------------
    def _finish(self, rec, record, decisions, close_reason, moves=()):
        record["close_reason"] = close_reason
        record["seconds"] = round(self.clock() - self.t_open - record["elapsed_s"], 2)
        if close_reason:
            record["closing"] = getattr(self, "_closing", None)
            log.info("%s: close (%s) -> %s", self.case_id, close_reason, decisions[0]["message"]["action"])
        record["moves"] = [
            {"supplier_id": m["st"]["sid"], "tactic": m["tactic"], "reason": m["reason"], "hold": m["hold"],
             "target_c": round(m["st"]["target"], 2), "c_now": round(m["st"]["c_now"], 2),
             "their_step": round(m["st"].get("their_step") or 0, 2), "our_step": m["st"].get("our_step"),
             "lock_in": m.get("lock"), "sheets": m.get("sent_sheets")}
            for m in moves
        ]  # fmt: skip
        if rec:
            rec.agent_round(**record)
            notes = [f"{m['supplier_id']}: tactic {m['tactic']} ({m['reason']})" for m in record["moves"]]
            if close_reason:
                notes.append(f"close: {close_reason}")
            rec.agent_note(f"DualAgent at {record['elapsed_s']:.0f}s - " + "; ".join(notes))
        return decisions

    def summary(self):
        """Tactic sequence per thread, for reports."""
        return dict(self.tactic_log)

